import { imageMeta } from "../data/imageMeta";

/** Resolves a root-relative asset path against Vite's BASE_URL (GitHub Pages safe). */
export function assetUrl(path: string): string {
  if (!path) return path;
  const base = import.meta.env.BASE_URL.endsWith("/") ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
  return `${base}${path.replace(/^\/+/, "")}`;
}

export interface ImageProps {
  src: string;
  srcSet: string;
  full: string;
  width?: number;
  height?: number;
  color: string;
}

/** Responsive variants (-sm 480w / -md 840w) generated by scripts/optimize-images.py */
export function imageProps(path: string): ImageProps {
  const meta = imageMeta[path];
  const stem = path.replace(/\.webp$/, "");
  return {
    src: assetUrl(`${stem}-md.webp`),
    srcSet: `${assetUrl(`${stem}-sm.webp`)} 480w, ${assetUrl(`${stem}-md.webp`)} 840w`,
    full: assetUrl(path),
    width: meta?.w,
    height: meta?.h,
    color: meta?.color ?? "#1a140a",
  };
}
